    if (!isset($cenas[$nome])) return '';
    $cena = $cenas[$nome];
    // as cenas antigas têm 3 itens; as novas trazem o preserveAspectRatio como 3º item
    $ajuste = count($cena) === 4 ? $cena[2] : 'xMidYMid meet';
    $svg = count($cena) === 4 ? $cena[3] : $cena[2];
    $atributos = ' preserveAspectRatio="' . $ajuste . '" fill="none" stroke="currentColor" stroke-width="' . $cena[1] . '" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"';
    return '<svg class="cena cena-' . $nome . '" viewBox="' . $cena[0] . '"' . $atributos . '>' . $svg . '</svg>';
